    17|function resolveConfiguredPasswordResetUrl(value: string): { url: string; rejectionReason: string | null } {
    18|  const trimmed = value.trim().replace(/\/$/, '');
    19|  if (!trimmed) {
    20|    return { url: '', rejectionReason: null };
    21|  }
    22|
    23|  try {
    24|    const parsed = new URL(trimmed);
    25|    if (looksLikeApiHost(parsed.hostname)) {
    26|      return {
    27|        url: '',
    28|        rejectionReason: `Configured auth URL uses API host ${parsed.hostname}, which cannot serve the public reset-password route.`,
    29|      };
    30|    }
    31|
    32|    if (trimmed.endsWith(PASSWORD_RESET_ROUTE_PATH)) {
    33|      return { url: trimmed, rejectionReason: null };
    34|    }
    35|
    36|    return { url: `${parsed.origin}${PASSWORD_RESET_ROUTE_PATH}`, rejectionReason: null };
    37|  } catch {
    38|    return { url: '', rejectionReason: 'Configured auth URL is not a valid HTTP URL.' };
    39|  }
